param([string]$XlsxPath, [string]$OutputPath)
Add-Type -AssemblyName System.IO.Compression.FileSystem
function Read-ZipText($zip, $name) { $entry=$zip.GetEntry($name); if(!$entry){return $null}; $reader=[IO.StreamReader]::new($entry.Open()); try{$reader.ReadToEnd()}finally{$reader.Dispose()} }
function Excel-Date($value) { if(!$value){return ''}; try{return [DateTime]::FromOADate([double]$value).ToString('yyyy-MM-dd')}catch{return "$value"} }
function Age-At($dateText) { if(!$dateText){return $null}; try{$birth=[datetime]::ParseExact($dateText,'yyyy-MM-dd',$null);$today=Get-Date;$age=$today.Year-$birth.Year;if($today -lt $birth.AddYears($age)){$age--};if($age -ge 0 -and $age -le 120){return $age};return $null}catch{return $null} }
function Required($value) { if($null -eq $value -or "$value".Trim() -eq ''){'Falta actualizar'}else{"$value".Trim()} }
function Optional($value) { if($null -eq $value){''}else{"$value".Trim()} }
function Choices($value, $labels, [bool]$required=$true) { if(!$value){if($required){return @('Falta actualizar')}else{return ,([object[]]@())}}; $found=@(); foreach($match in [regex]::Matches("$value",'(?<!\d)(?:1[0-3]|[1-9])(?!\d)')){$key=[int]$match.Value;if($labels.ContainsKey($key) -and $found -notcontains $labels[$key]){$found += $labels[$key]}}; if($found.Count){return $found}; return @("$value".Trim()) }
function Pick-Code($value, $labels, [bool]$required=$true) { if(!$value){if($required){return 'Falta actualizar'}else{return ''}}; $match=[regex]::Match("$value",'^\s*(\d+)'); if($match.Success -and $labels.ContainsKey([int]$match.Groups[1].Value)){return $labels[[int]$match.Groups[1].Value]}; return (Optional $value) }
function Yes-No($value, [bool]$required=$true) { if(!$value){if($required){return 'Falta actualizar'}else{return ''}}; if("$value" -match '^\s*S[IÍ]\s*$'){return 'Sí'}; if("$value" -match '^\s*NO\s*$'){return 'No'}; return (Optional $value) }
function Document-Type($value) { if(!$value){return 'Falta actualizar'}; $text="$value".ToUpperInvariant(); if($text -match 'EXTRANJER'){return 'CE · Cédula de extranjería'};if($text -match 'TARJETA'){return 'TI · Tarjeta de identidad'};if($text -match 'REGISTRO'){return 'RC · Registro civil'};if($text -match 'PASAPORTE'){return 'PAS · Pasaporte'};if($text -match 'PERMISO'){return 'PEP · Permiso especial de permanencia'};if($text -match 'SIN INFORM'){return 'SI · Sin información'};if($text -match 'UNICO'){return 'NUI · Número único de identificación'};if($text -match 'IDENTIFICACION PERSONAL'){return 'NUIP · Número de identificación personal'};if($text -match 'CEDULA'){return 'CC · Cédula de ciudadanía o contraseña'};return (Optional $value) }
$productive=@{1='1 · Minería tradicional';2='2 · Agricultura';3='3 · Corte de madera';4='4 · Silvicultura';5='5 · Pesca artesanal';6='6 · Comercio';7='7 · Artesanía';8='8 · Otra';9='9 · Ninguna'}
$roles=@{1='1 · Curandero(a) de mordeduras';2='2 · Curandero(a) de ojo';3='3 · Curandero(a) de espanto';4='4 · Cantor(a) de alabaos';5='5 · Sobandero(a)';6='6 · Partero(a)';7='7 · Decimero(a)';8='8 · Cuentero(a)';9='9 · Cazador(a)';10='10 · Mayor sabedor(a)';11='11 · Maestro(a) etnoeducador(a)';12='12 · Músico tradicional';13='13 · Poeta'}
$communities=@{'Concepción'='100 · Concepción';'Santa Rosa'='200 · Santa Rosa';'San Antonio'='300 · San Antonio';'San José'='400 · San José';'El Carmelo'='500 · El Carmelo';'Limones'='600 · Limones';'Quiroga'='700 · Quiroga 1';'Joanico'='800 · Joanico';'Juanico'='802 · Juanico'}
$zip=[IO.Compression.ZipFile]::OpenRead($XlsxPath)
try {
  $strings=@(); $sharedText=Read-ZipText $zip 'xl/sharedStrings.xml'; if($sharedText){[xml]$shared=$sharedText;foreach($item in $shared.sst.si){$strings+=(($item.SelectNodes('.//*[local-name()="t"]')|%{$_.InnerText})-join '')}}
  [xml]$sheet=Read-ZipText $zip 'xl/worksheets/sheet1.xml'; $results=@(); $lastHousehold=''; $lastFamily=''
  foreach($row in $sheet.SelectNodes('//*[local-name()="sheetData"]/*[local-name()="row"]')){
    if([int]$row.r -le 1){continue}; $cells=@{}; foreach($cell in $row.SelectNodes('./*[local-name()="c"]')){$col=([regex]::Match($cell.r,'[A-Z]+')).Value;$value=if($cell.t -eq 's'){$strings[[int]$cell.v]}elseif($cell.t -eq 'inlineStr'){$cell.is.t}else{$cell.v};$cells[$col]=$value}
    if(!("$($cells.H)$($cells.J)$($cells.O)".Trim())){continue}
    $community=Optional $cells.C; if(!$community){$community=Required $cells.W}; if($communities.ContainsKey($community)){$community=$communities[$community]}
    if($cells.D){$lastHousehold=(Optional $cells.D);$lastFamily=''}; $household=if($lastHousehold){$lastHousehold}else{'Falta actualizar'}
    if($cells.E){$lastFamily=(Optional $cells.E)}elseif(!$lastFamily){$lastFamily='1'}; $family=if($household -ne 'Falta actualizar'){"$household.$lastFamily"}else{'Falta actualizar'}
    $person=if($household -ne 'Falta actualizar' -and $cells.F){"$family.$(Optional $cells.F)"}else{'Falta actualizar'}; $docType=Document-Type $cells.N; $docNumber=if($docType -like 'SI ·*'){Optional $cells.O}else{Required $cells.O}; $birthDate=Excel-Date $cells.P; $cleanAge=Age-At $birthDate
    $canWrite=if($null -ne $cleanAge -and $cleanAge -lt 5 -and !$cells.AC){'No aplica'}else{Yes-No $cells.AC}; $canRead=if($null -ne $cleanAge -and $cleanAge -lt 5 -and !$cells.AD){'No aplica'}else{Yes-No $cells.AD}; $studying=if($null -ne $cleanAge -and $cleanAge -lt 3 -and !$cells.AE){'No aplica'}else{Yes-No $cells.AE}; $academic=if($null -ne $cleanAge -and $cleanAge -lt 5 -and !$cells.AG){'No aplica'}else{Pick-Code $cells.AG @{1='1 · Bachiller';2='2 · Técnica';3='3 · Tecnológica';4='4 · Universitaria';5='6 · Ninguna';6='6 · Ninguna'}}; $activities=if($null -ne $cleanAge -and $cleanAge -lt 15 -and !$cells.AH){@('No aplica')}else{Choices $cells.AH $productive}
    $answers=[ordered]@{
      community=$community;censusDate=Required (Excel-Date $cells.B);householdCode=$household;familyCode=$family;personCode=$person;relationship=Pick-Code $cells.G @{1='1 · Jefe(a)';2='2 · Cónyuge o compañero(a)';3='3 · Hijo(a) o hijastro(a)';4='4 · Padre, madre, padrastro o madrastra';5='5 · Hermano(a) o hermanastro(a)';6='6 · Otro pariente del jefe'}
      firstName=Required $cells.H;middleName=Optional $cells.I;lastName1=Required $cells.J;lastName2=Optional $cells.K;lastName3=Optional $cells.L;lastName4=Optional $cells.M
      documentType=$docType;documentNumber=$docNumber;birthDate=Required $birthDate;age='';sex=$(if($cells.R -match '^HOMBRE$'){'H · Hombre'}elseif($cells.R -match '^MUJER$'){'M · Mujer'}elseif($cells.R -match 'INTERSEXUAL'){'I · Intersexual'}else{Required $cells.R});sexualOrientation=Pick-Code $cells.S @{1='1 · Heterosexual';2='2 · Homosexual';3='3 · Bisexual';4='4 · Asexual';5='5 · No sabe / No informa'} $false;genderIdentity=Pick-Code $cells.T @{1='1 · Masculino';2='2 · Femenino';3='3 · Transgénero';4='4 · No sabe / No informa'} $false
      disability=Choices $cells.U @{1='1 · Física';2='2 · Visual';3='3 · Auditiva';4='4 · Intelectual';5='5 · Mental';6='6 · Sordoceguera';7='7 · Múltiple';8='8 · Ninguna'}
      ethnicity=$(if($cells.V -match 'AFRO'){'Afrocolombiano(a)'}elseif($cells.V -match '^NEGRO'){'Negro(a)'}elseif($cells.V -match 'RAIZAL'){'Raizal'}elseif($cells.V -match 'PALEN'){'Palenquero(a)'}elseif($cells.V -match 'MESTIZ'){'Mestizo(a)'}elseif($cells.V -match 'BLANC'){'Blanco(a)'}elseif($cells.V -match 'IND[IÍ]GEN'){'Indígena'}else{Required $cells.V});residence=Required $cells.W;phone=Optional $cells.X;email='';department=Required $cells.Y;municipality=Required $cells.Z;sisben='Falta actualizar';eps=Required $cells.AA;sisbenLevel=Optional $cells.AB
      canWrite=$canWrite;canRead=$canRead;currentlyStudying=$studying;lastGrade=Optional $cells.AF;academicLevel=$academic;productiveActivities=$activities;familyHectares=Optional $cells.AI;traditionalRoles=Choices $cells.AJ $roles $false
      familiasAccion='Falta actualizar';rentaCiudadana='Falta actualizar';adultoMayor='Falta actualizar';enumeratorName=Optional $cells.AK;enumeratorDocument=Optional $cells.AL;enumeratorPhone=Optional $cells.AM;enumeratorEmail=Optional $cells.AN
    }
    $results += [ordered]@{id="censo-importado-$($row.r)";surveyId='censo-interno-guajui';submittedAt='2026-08-19T12:00:00.000Z';sourceRow=[int]$row.r;answers=$answers}
  }
  $json=$results|ConvertTo-Json -Depth 8 -Compress
  [IO.File]::WriteAllText($OutputPath,"export default $json;`n",[Text.UTF8Encoding]::new($false))
  Write-Output "Registros generados: $($results.Count)"
} finally {$zip.Dispose()}
